recipes.code:
{
  "inputs": [
    {
      "id": "astrocal-api-key",
      "type": "promptString",
      "description": "Your Astrocal API key (create one at https://astrocal.dev/dashboard/connect)",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@astrocal/mcp-server@0.1.6"
      ],
      "env": {
        "ASTROCAL_API_KEY": "${input:astrocal-api-key}",
        "ASTROCAL_API_URL": "<astrocal-api-url>",
        "ASTROCAL_DEFAULT_EVENT_TYPE_ID": "<astrocal-default-event-type-id>"
      }
    }
  }
}
